head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	// 값 변경 시 col2의 inputType을 동적으로 변경한다.
	var gvItem = function() { return [{ ref: "label", header: "LABEL" }, { ref: "value", header: "VALUE" }, { ref: "col3", header: "COL3" }]; };
	scwin.inputTypeCustomObj = {
		calendar: { inputType: "calendar" },
		radio: { inputType: "radio" },
		checkbox: { inputType: "checkbox" },
		input: { inputType: "text" },
		select: {
			inputType: "select",
			options: { viewType: "default" },
			itemSet: { nodeset: "data:sel_sample", label: "col1", value: "col2" }
		},
		autoComplete: {
			inputType: "autoComplete",
			options: { viewType: "default" },
			itemSet: { nodeset: "data:sel_sample", label: "col1", value: "col2" }
		},
		select_gridViewItemset: {
			inputType: "select",
			nodeset: "data:dataList2",
			label: "label",
			value: "value",
			item: gvItem(),
			itemTableType: "gridViewItemset",
			width: "330",
			visibleRowNum: "3",
			rowNumVisible: "true",
			hideHeader: "true"
		},
		autoComplete_gridViewItemset: {
			inputType: "autoComplete",
			nodeset: "data:dataList2",
			label: "label",
			value: "value",
			item: gvItem(),
			itemTableType: "gridViewItemset",
			width: "330",
			visibleRowNum: "3",
			rowNumVisible: "true",
			hideHeader: "true"
		},
		checkcombobox_gridViewItemset: {
			inputType: "checkcombobox",
			nodeset: "data:dataList2",
			label: "label",
			value: "value",
			item: [{ inputType: "checkbox", ref: "col3", header: "COL3" }, { ref: "label", header: "LABEL" }, { ref: "value", header: "VALUE" }],
			itemTableType: "gridViewItemset",
			width: "170",
			visibleRowNum: "3",
			rowNumVisible: "true",
			checkColumn: "0"
		}
	};
	scwin.init();
};
scwin.init = function() {
	var types = ["select_gridViewItemset", "autoComplete_gridViewItemset", "checkcombobox_gridViewItemset", "autoComplete", "input", "calendar", "checkbox", "select", "radio"];
	dlt_select.setJSON(types.map(function(t) { return { "label": t, "code": t }; }));
	sel_sample.setJSON([
		{ "col1": "축구", "col2": "1" },
		{ "col1": "농구", "col2": "2" },
		{ "col1": "야구", "col2": "3" },
		{ "col1": "배구", "col2": "4" }
	]);
	var arr = [];
	for (var i = 0; i < 5; i++) {
		arr.push(new Array);
	}
	dataList1.setJSON(arr);
	var dl_json = [];
	for (var j = 1; j <= 5; j++) {
		dl_json.push({ "label": "라벨" + j, "value": "값" + j, "col3": "" });
	}
	dataList2.setJSON(dl_json);
};
scwin.grd_onviewchange = function(info) {
	var inputType = info.newValue;
	var obj = scwin.inputTypeCustomObj[inputType];
	if (obj) {
		grd.setCellInputType(info.rowIndex, "col2", obj);
	}
};
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
}
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
}
